lines = [l.strip() for l in user_text.split('\n') if l.strip()]
print(f"Total lines: {len(lines)}")

errors = []
entries = []
seen = set()

for line in lines:
    m = re.match(r'^(\d{3,4})[_\s]+(.+)$', line)
    if not m:
        errors.append(f"Malformed: {line[:40]}")
    else:
        idx = int(m.group(1))
        if idx in seen:
            errors.append(f"Duplicate: {idx}")
        seen.add(idx)
        entries.append(idx)

print("Entries count:", len(entries))
print("Errors count:", len(errors))
print("Min:", min(entries) if entries else None, "Max:", max(entries) if entries else None)

# Check continuity:
if entries:
    for i in range(min(entries), max(entries) + 1):
        if i not in seen:
            errors.append(f"Missing {i}")

print("Continuity errors:", errors)
